import sys
def _fail(t, e, tb, _d=sys.excepthook):
    if issubclass(t, AssertionError):
        print("check failed:", e)
        sys.exit(1)
    _d(t, e, tb)
sys.excepthook = _fail
import json, os, sys, tempfile
sys.path.insert(0, "_tools")
import tests
def prof(v):
    t = tempfile.mkdtemp()
    os.makedirs(os.path.join(t, "_private"))
    open(os.path.join(t, "_private", "host.json"), "w").write(json.dumps({"profile": v}))
    return tests.read_profile(home=t)
got = {}
for v in (["busy"], 3, None, 1.5, {"a": 1}, True):
    try:
        got[repr(v)] = prof(v)
    except Exception as e:
        got[repr(v)] = type(e).__name__
bad = {k: g for k, g in got.items() if g != "usual"}
assert not bad, ("a host.json profile that is not a string is not read as usual", bad)

